        "content": "むかし、足柄山（あしがらやま）の 山奥に、金太郎という 名前の 元気な 男の子が すんでいました。\n金太郎は いつも 赤い 前掛けを して、大きな まさかりを 肩に 担いで いました。\n\n金太郎は 生まれた時から 力持ちでした。\nお母さんが「金太郎、薪を 割っておくれ」と 頼むと、大きな 木を 一振りで ぱかーんと 割りました。\n金太郎の 友達は、山の 動物たちでした。\n熊、鹿、猿、兎たちが、毎朝 金太郎の 家の 前に 集まって きます。\n\n「金太郎、今日も 相撲を 取ろう！」\n金太郎と 動物たちは、草の上で 相撲大会を 開きました。\n「はっけよい、残った、残った！」\n兎も 猿も、金太郎には かないません。\n最後に、大きな 黒熊が 出てきました。\n黒熊は 山で 一番 強い 動物です。\n「金太郎、俺と 勝負だ！」\n金太郎と 熊は、がっちりと 組み合いました。\n「よいしょ、よいしょ！」\n二人とも 力を 込めて 押し合います。\n最後に 金太郎が「えいっ！」と 声を 上げて 投げ飛ばすと、大きな 熊が どすーんと 倒れました。\n\n「参った、参った！ 金太郎は 日本一の 力持ちだ。」\n熊は 降参して、金太郎と 一番の 仲良しに なりました。\n\nある日、金太郎と 動物たちが 谷川の 近くを 歩いていると、橋が なくて 渡れませんでした。\n向こう岸に 行けなくて、子鹿や 兎が 困っていました。\nすると 金太郎は、近くに 生えていた 大きな 杉の 木に 近づきました。\n「みんな、待っていなさい。僕が 橋を 作ってあげるよ。」\n金太郎は 木に 手を かけて、力いっぱい ぐいぐいと 押しました。\nメリメリメリ、ドシーン！\nなんと、大きな 木が 根元から 折れて、川の 上に 倒れ、立派な 橋に なりました。\n\n「わあ、金太郎、すごい！」\n動物たちは 大喜びで 橋を 渡りました。\nその様子を、通りかかった 偉い お侍さんが 見ていました。\n「なんと 素晴らしい 少年だ。ぜひ 私の 家来にして、立派な 武士に 育てたい。」\n\n金太郎は お母さんに 感謝して、都へ 行き、坂田金時（さかたのきんとき）という 立派な 侍に なって、国を 守る 英雄に なりましたとさ。"
