        "content": "むかしむかし、子供の いない おじいさんと おばあさんが いました。\n二人は 毎朝、神社へ お参りに 行き、「指の先ほどの 小さな 子供でも いいですから、どうぞ 授けてください」と お祈りしました。\n\nやがて、おばあさんに 男の子が 生まれました。\nしかし、その 子は 何年 たっても 背が 伸びず、ちょうど 一寸（約三センチ）の 大きさしか ありませんでした。\nそこで、二人は その 子を「一寸法師（いっすんぼうし）」と 名付け、大切に 育てました。\n\n一寸法師は 体は 小さいけれど、とても 賢く、勇気のある 少年でした。\nある日、一寸法師は 両親に 言いました。\n「お父さん、お母さん。私は 都へ 行って、立派な 侍に なりたいと 思います。」\n二人は 心配しましたが、一寸法師の 志を 認めて、旅の 支度を してあげました。\nおばあさんは 裁縫の 針を 刀の 代わりに くれました。\n麦わらを 鞘（さや）にして、腰に 差しました。\nおじいさんは お椀を 船に、お箸を 櫂（かい）にして 持たせてくれました。\n\n「行ってまいります！」\n一寸法師は 川に お椀を 浮かべ、お箸で 水を 漕ぎながら、都を 目指しました。\n\n何日も かけて 都に 着いた 一寸法師は、一番 大きな お屋敷を 訪ねました。\nそこは、大臣の 屋敷でした。\n「ごめんください。私は 一寸法師と 申します。どうか お使いください。」\n大臣は 一寸法師の 小ささに 驚きましたが、その 賢さを 気に入り、美しい 娘（姫）の 護衛に 任命しました。\n姫は 一寸法師を とても 可愛がり、一寸法師も 姫を 一生懸命 守りました。\n\nある日、姫が 清水寺へ お参りに 行く 途中で、二匹の 恐ろしい 鬼が 現れました。\n「美しい 姫だ。連れて帰って 嫁に しよう！」\n一寸法師は 針の 刀を 抜いて、叫びました。\n「姫には 指一本 触れさせないぞ！」\n鬼は 笑って、一寸法師を ひょいと つまみ、口の中に 飲み込んで しまいました。\n\nお腹の中に 入った 一寸法師は、針の 刀で 鬼の 胃袋を ちくちくと 刺しました。\n「痛い、痛い！ 助けてくれ！」\n鬼は 痛みに 耐えかねて、一寸法師を 吐き出しました。\nもう 一匹の 鬼が 襲いかかってきましたが、一寸法師は 鬼の 目に 飛びかかり、針で つつきました。\n「参った、逃げろ！」\n鬼たちは 泣きながら 逃げていきました。\n\n地面を 見ると、鬼が 落としていった「打出の小槌（うちでのこづち）」が 転がっていました。\n姫は 大喜びで 言いました。\n「これは 欲しいものを 出してくれる 宝物よ。一寸法師、背が 高くなりたいと 願ってみて！」\n姫が 小槌を 振ると、\n「大きくなれ、大きくなれ！」\n一寸法師の 体は ぐんぐんと 伸びて、立派で 男らしい 若者に なりました。\n\n一寸法師は 姫と 結婚し、両親も 都に 呼び寄せて、みんなで 幸せに 暮らしましたとさ。"
