        "content": "むかしむかし、竹を取って 暮らしている「讃岐の造（さぬきのみやつこ）」という おじいさんが いました。\nある日、竹林へ 行くと、根元が ピカピカと 光り輝く 不思議な 竹が 一本 ありました。\n\n「おや、これは 何だろう？」\n不思議に 思って その 竹を 切り倒してみると、なんと 竹の 筒の中に、三寸（約九センチ）ほどの 小さくて 愛らしい 女の子が 座っていました。\n\n「神様が 授けてくださったに 違いない。」\nおじいさんは 大喜びで その 子を 家へ 連れて帰り、おばあさんと 一緒に 我が子のように 育てました。\nそして、その 子に「かぐや姫」と 名付けました。\n\nそれからというもの、おじいさんが 竹林へ 行くたびに、竹の 節の中から 小判が ざくざくと 見つかりました。\nおじいさんの 家は たちまち 大金持ちに なりました。\nかぐや姫は わずか 三ヶ月ほどで、この世の ものとは 思えないほど 美しい 娘に 成長しました。\n\nかぐや姫の 美しさは たちまち 国中に 広まりました。\nたくさんの 貴族や 殿方が、かぐや姫を 妻に したいと 求婚に やってきました。\nしかし、かぐや姫は 誰とも 結婚する 気は ありませんでした。\n熱心な 五人の 貴族に対し、かぐや姫は「この世に ない 珍しい 宝物を 持ってきてくださった方の 妻に なります」と 言いました。\n「仏の御石の鉢」「蓬莱の玉の枝」「火鼠の皮衣」「竜の首の珠」「燕の子安貝」。\n貴族たちは 宝を 探そうと 必死に なりましたが、偽物を 作ったり、嵐で 船が 沈んだりして、全員 失敗してしまいました。\n\nやがて、国の 帝（みかど）までもが かぐや姫を 召し出そうと しましたが、かぐや姫は 丁重に 断りました。\n\n三年の 月日が 流れました。\n夏に なると、かぐや姫は 夜ごとに 月を 見上げては、悲しそうに 涙を 流すように なりました。\n心配した おじいさんが 尋ねると、かぐや姫は 泣きながら 告白しました。\n「お父さん、お母さん。私は 実は この世界の 人間ではなく、月の 都の 者なのです。\n次の 満月の 夜に、月の 都から 迎えが やってきて、帰らなければ ならないのです。」\n\nおじいさんと おばあさんは 驚き、悲しみました。\n「そんなことは させない！」\n帝も かぐや姫を 守るため、二千人の 武士を 屋敷の 周りに 配備しました。\n\n八月十五日の 満月の 夜。\n空が 昼間のように 明るくなり、雲に 乗った 月の 天人たちが 降りてきました。\n武士たちは 弓を 引こうと しましたが、不思議な 光に 打たれて、力が入らなくなって しまいました。\n\nかぐや姫は 育ててくれた 両親に 涙ながらに 感謝の 言葉を 述べ、帝には 不老不死の 薬と 手紙を 残しました。\nそして、「羽衣（はごろも）」を 着せられると、地上の 記憶を すべて 忘れ、静かに 月の 都へと 帰っていきました。\n\n残された おじいさんと おばあさんは 嘆き悲しみました。\n帝は「かぐや姫の いない この世で、不老不死の 薬など 何の 役に立とうか」と 言い、日本で 一番 高い 山の 頂上で その 薬と 手紙を 焼かせました。\nその 山から 煙が 立ち上り続けたことから、その 山は「富士山（ふじさん / 不死の山）」と 呼ばれるように なったと 伝えられています。"
