        "content": "東京での生活を始めるために、まず区役所へ行って「住民登録」をしなければなりませんでした。\n駅から歩いて十分ほどの場所に、ガラス張りの大きな区役所がありました。\n受付で「在留カード」を見せると、案内係の職員が親切に対応してくれました。\n\n「外国人登録の窓口は二階の三番です。こちらの番号札を持ってお待ちください。」\n待合室の掲示板には、多言語で書かれた案内パンフレットがたくさん置いてありました。\n自分の番号が呼ばれたので窓口へ行き、住所や生年月日を記入した書類を提出しました。\n職員の方はゆっくりとした優しい日本語で話してくれたので、私のN4レベルの語学力でも十分に理解できました。\n\n手続きが終わると、職員の方から「ごみの分別ガイドブック」を手渡されました。\n「日本では、燃えるごみ、燃えないごみ、プラスチック、資源ごみ（缶、瓶、ペットボトル）を曜日ごとに分けて出します。\n必ず指定の透明な袋を使ってくださいね。」\n\n部屋へ帰ってから、ガイドブックをじっくり読みました。\nペットボトルのキャップとラベルを外して洗ってから捨てるなど、とても細かいルールがありました。\n地域社会の一員として、日本のルールをしっかりと守って暮らしていこうと心に誓いました。"
