        "readingTime": "3 phút",
        "summary": "Học cách tắm đúng chuẩn của người Nhật và cảm nhận nét ấm áp của văn hóa tắm nước nóng cộng đồng.",
        "content": "日本の文化を体験するために、近所にある昔ながらの「銭湯（せんとう）」へ行きました。\n暖簾（のれん）をくぐると、番台におばあさんが座っていました。\n入浴料を払って脱衣所へ入ると、体重計や扇風機が置いてあり、昭和の懐かしい雰囲気が漂っていました。\n\n浴室に入ると、壁一面に富士山の雄大なペンキ絵が描かれていました。\n銭湯には大切なお風呂マナーがあります。\n湯船に入る前に、まず洗い場で体を石鹸で綺麗に洗わなければなりません。\nまた、持参したタオルを湯船の中につけてはいけません。\n\n体をよく洗ってから、大きな湯船にゆっくりと足を入れました。\n「熱い！」\n最初はお湯がとても熱く感じましたが、肩まで浸かると、全身の筋肉がほぐれていくのが分かりました。\nお湯から上がった後は、脱衣所のベンチに座って、冷たい「瓶入りコーヒー牛乳」を一気に飲み干しました。\n常連のおじいさんが「いい湯だったかい？」と声をかけてくれました。\n地域の温かい繋がりを感じられる、素晴らしい体験でした。"
