        "content": "これは、私が 小さいときに、村の 茂平という おじいさんから 聞いた お話です。\n\nむかし、私たちの 村の 近くの 中山という 所に、小さなお城が ありました。\nそして、その 近くの 山には「ごん」という 名前の いたずら好きな 小ぎつねが すんでいました。\nごんは ひとりぼっちで、森の 草むらに かくれながら、村へ 出てきては いたずらばかり していました。\n\nある秋のこと、雨が 何日も 降り続いた後、ごんは 川へ 行きました。\n川には、村の 兵十（ひょうじゅう）という 若者が、腰まで 水に つかって 魚を とっていました。\n兵十が いなくなった すきに、ごんは いたずら心を 起こし、魚籠（びく）の 中の ウナギを つかみ出して、逃げてしまいました。\n\nそれから 十日ほど たった日、兵十の 家の 前を 通ると、村の 人たちが 集まって 葬式を していました。\n「兵十の お母さんが 亡くなったんだな。」\nごんは 思い出しました。あの時、兵十が 川で とっていた ウナギは、病気の お母さんに 食べさせるための ものだったのです。\n「ああ、俺は とりかえしの つかない 悪いことを してしまった。」\nごんは 深く 後悔しました。\n\nそれから、ごんは 罪滅ぼしを しようと 決めました。\n毎日、毎日、山で 栗や 松茸を 拾っては、兵十の 家の 納屋へ こっそり 届けました。\n「兵十、これは 俺からの 贈り物だよ。」\n\n兵十は、毎朝 届けられる 栗や 松茸を 見て、不思議で たまりませんでした。\n「一体 誰が、こんなに 親切に してくれるのだろう。神様が 恵んでくださるに 違いない。」\n兵十は 友達の 加助に そう 話しました。\n物陰で それを 聞いていた ごんは、「神様じゃなくて、俺なんだよ」と 心の中で つぶやきました。\n\n次の日も、ごんは 栗を たくさん 抱えて、兵十の 家へ 忍び込みました。\nちょうど その時、兵十が 納屋に 入ってきました。\n「あっ、あの いたずら狐の ごんだな！ また 俺の 家に いたずらを しに きたな！」\n\n兵十は 立ち上がり、火縄銃を 取って、引き金を 引きました。\nズドン！\n煙が 晴れると、ごんは 倒れていました。\n兵十が 駆け寄ると、土間に 固く 握られた 瑞々しい 栗が こぼれ落ちていました。\n\n「……ごん、お前だったのか。いつも 栗を くれたのは。」\nごんは、ぐったりと 目を つぶったまま、かすかに うなずきました。\n兵十の 手から 火縄銃が ぽろりと 落ち、青い 煙が まだ 銃口から 細く 出ていました。"
