        "readingTime": "6 phút",
        "summary": "Hai chàng quý tộc thành thị lạc vào quán ăn kỳ lạ trong rừng sâu và bài học sâu cay của tự nhiên.",
        "content": "二人の若い紳士が、すっかりイギリスの兵隊のかたちをして、ピカピカする鉄砲をかついで、白熊のような大きな犬を二匹つれて、山奥を歩いておりました。\nところが、どうしたことか、山は恐ろしく深く、案内人はいなくなり、連れてきた犬も二匹とも泡を吹いて倒れて死んでしまいました。\n二人は寒さと空腹と恐怖で、青ざめてしまいました。\n「もう帰ろう。腹が減ってたまらない。」\n「ああ、早く暖かい宿へ行って、酒でも飲んで飯を食いたいものだ。」\n\n二人がそう言って藪の中を見回したとき、ふと後ろを見ますと、立派な西洋風の館が一軒ありました。\n玄関には看板が掲げてあり、金文字でこう書かれていました。\n『西洋料理店　山猫軒』\n二人は大喜びしました。\n「こんな山奥に西洋料理店があるとは！ これで助かった。」\n\n二人が扉を開けて中に入ると、ガラスの扉に青い字でこう書いてありました。\n『どなたもどうかお入りください。決してご遠慮はありません。』\n二人は喜んで先へ進みました。\nしかし、進むにつれて扉が現れ、そのたびに不思議な注文が書かれていました。\n『当軒は注文の多い料理店ですから、どうかその点をご承知ください。』\n『鉄砲と弾丸をここに置いてください。』\n『帽子と外套、靴をお脱ぎください。』\n二人は「なるほど、よほど高級な店なのだな」と納得して、言われるがままに衣服や武器を脱ぎ捨てていきました。\n\nさらに進むと、銀色の鏡と、小さな香水の瓶が置いてありました。\n『瓶の中の香水を、お顔と手足にしっかりとお塗りください。』\n二人は香水を体に塗りたくりましたが、どうも酢のような匂いがします。\n次の扉にはこうありました。\n『壺の中の塩を、残らず体中によく揉み込んでください。』\nここで、二人の紳士はようやく顔を見合わせました。\n\n「おい……これはどういうことだ？」\n「香水じゃなくて、酢だった。それに塩を揉み込むって……」\n「まさか！ 『注文の多い料理店』というのは、客が料理を注文するんじゃなくて、客を料理して食うための注文だったんだ！」\n二人はガタガタと震え上がり、泣き出しました。\n\n最後の扉の鍵穴から、二つの青い光る眼がこちらを覗き込み、ペロリと舌なめずりをする音が聞こえてきました。\n「おい、早く入っておいで。頭に塩をすり込んで、お皿の上にお乗り。」\n二人は恐怖のあまり、言葉も出ずに泣きじゃくりました。\n\nその時です。\nバタン！ と後ろの扉が破れ、死んだはずの二匹の白熊のような犬が猛然と飛び込んできました。\n激しい唸り声とともに奥の部屋へ飛び込み、ドタバタと激しい格闘の音が響きました。\nやがて館は煙のように消え失せ、二人の紳士は寒風の吹き荒れる草むらの中に、衣服を剥ぎ取られた姿で立ち尽くしておりましたとさ。"
