        "readingTime": "6 phút",
        "summary": "Cuộc hạnh ngộ định mệnh tại bờ biển Kamakura và bóng tối tâm lý bí ẩn của người thầy trí thức.",
        "content": "私はその人を常に先生と呼んでいた。だからここでもただ先生と書くだけで本名は明かさない。\nこれは世間を憚る遠慮というよりも、その方が私にとって自然だからである。\n私はその人の記憶を呼び起こすごとに、すぐ「先生」と言いたくなる。筆を執っても心持ちは同じ事である。\n\n私が先生と知り合ったのは鎌倉であった。\n当時の私はまだ若い書生で、夏休みを利用して海辺へ泳ぎに行ったのである。\n雑踏の中で、私は一人の西洋人を連れた先生を偶然見かけた。\n何故か先生の端正な風貌と、どこか世俗を離れたような寂しげな眼差しが、私の脳裏に強く焼き付いて離れなかった。\n\n東京へ帰ってからも、私は先生の宅へ出入りするようになった。\n先生は美しい奥さんと二人きりで、静かな、あまりに静かな生活を送っておられた。\n先生は博学でありながら、職に就こうともせず、毎月一度、雑司ヶ谷の墓地へ一人で墓参りに行かれる習慣があった。\n私がその墓の主について尋ねても、先生はただ憂鬱な表情を浮かべるだけで、決して真相を語ろうとはなさらなかった。\n\n「あなたには、人間の罪というものが分かりますか。」\nある日、書斎で先生は私にそう問いかけられた。\n「私はね、昔は純粋な人間だったのです。しかし、一度の過ちが、私を永遠に人間不信の底へと突き落としました。\n私は他人も信じられないが、何よりも自分自身をこれっぽっちも信じていないのです。」"
