        "summary": "Bức thư tuyệt mệnh xé toang quá khứ: Tình yêu, sự phản bội người bạn thân K và bản án lương tâm vĩnh viễn.",
        "content": "後になって私の手元へ届いた先生からの長大な遺書によって、私はようやくすべての真相を知ることになる。\n学生時代、先生は親友の「K」と同じ下宿に住み、下宿屋の美しい娘（後の奥さん）を同時に愛してしまったのであった。\nKは謹厳実直な求道者でありながら、自らの恋情に悩み、その苦悩を先生に打ち明けた。\nしかし、先生は友の純粋な告白を前にして激しい嫉妬に駆られ、卑劣な罠を仕掛けたのである。\n\n「精神的に向上心のないものは、馬鹿だ。」\nかつてK自身が口にした厳しい戒律を逆手に取って、先生は友の恋心を冷酷に嘲笑した。\nそして、Kが懊悩して口を閉ざしている隙を突き、密かに下宿の小母さんに談判して、娘との婚約を取り付けてしまったのである。\n\nその事実を知った数日後の夜、Kは自らの喉を剃刀で掻き切って絶命した。\n机の上には「もっと早く死ぬべきだったのに、今まで生きていたのが間違いだった」という短い遺書が残されていた。\n先生に対する恨み言は一言も書かれていなかった。その寛大さが、かえって先生の胸に消えない業火の傷を焼き付けたのである。\n\n「私はKの血に塗られた布団を見た瞬間から、自分自身が生きていてはならない人間だと悟りました。\n私は罪の重さに耐えかねて、ただ死ぬ勇気もなく、死んだように生き永らえてきたのです。\n明治天皇の崩御、そして乃木将軍の殉死の報に接した時、私は明治の精神に殉職する決意を固めました。」\n\n手紙の最後には、この恐ろしい告白を妻には決して明かさないでほしいという、切実な懇願が記されていた。"
