        "readingTime": "6 phút",
        "summary": "Lòng tự tôn hèn hạ và tính tự phụ ngút trời đã biến một thi nhân lỗi lạc thành thú dữ nơi rừng sâu.",
        "content": "隴西（ろうせい）の李徴（りちょう）は博学才穎、天宝の末年に若くして官吏の試験に合格した。\nしかし、その自尊心の高さゆえに、卑しい官職に甘んじることを潔しとせず、詩人として名を後世に遺そうと官を辞した。\nだが、文名は容易に揚がらず、生活は窮乏を極めた。\n妻子を養うため、李徴は自尊心を屈して再び地方の下級官吏に就いたが、かつて見下していた同僚の下風に立つことに耐えられず、やがて発狂して山中へ姿を消した。\n\n翌年、監察御史の袁傪（えんさん）が旅の途次、山道を通過していると、草むらから一頭の猛虎が躍り出て襲いかかってきた。\n虎は袁傪の顔を見るや、身を翻して茂みに隠れ、人間の言葉で叫んだ。\n「あぶないところであった！」\nその声は、袁傪の旧友・李徴その人の声であった。\n\n袁傪は驚き、茂みに向かって呼びかけた。\n「友よ、なぜそのような姿になってしまったのか。」\n茂みの奥から、忍び泣く声とともに李徴の告白が漏れ聞こえてきた。\n\n「私は自らの『臆病な自尊心』と『尊大な羞恥心』によって虎になったのだ。\n私は詩人として名を成そうとしながら、師に就いて切磋琢磨することもせず、かといって俗物に伍することも拒んだ。\n己の珠玉ならざるを恐れ、かつ己の瓦礫ならざるを信ずるがゆえに、内に飼い慣らしていた猛獣が、とうとう私の外形までも虎に変えてしまったのだ。\n人間であった頃の記憶が薄れ、完全に獣の心へと同化していくのが何よりも恐ろしい。」\n\n李徴は自作の詩を袁傪に託し、妻子への扶助を懇願した。\n別れ際、丘の上に現れた一頭の虎は、青白い月光に向かって咆哮し、深い密林の中へと永遠に姿を消した。"
