    "readingTime": "5 phút",
    "summary": "Hai người thợ săn lạc bước vào tòa biệt thự rừng sâu với những cánh cửa kỳ lạ yêu cầu tự bôi gia vị lên người.",
    "content": "二人の若い紳士が、ぴかぴかする鉄砲を担いで、白熊のような大きな犬を二匹連れて、深い山の中を歩いていました。\n「この山はけしからん。鳥も獣も一匹も居らんではないか。」\n二人がそう言いながら引き返そうとしたとき、ふと見ると、立派な西洋風の館が現れました。\n玄関には「西洋料理店 山猫軒」という看板が掲げてありました。\n「どなたもどうかお入りください。決してご遠慮はありません」と書いてあります。\nお腹が空いていた二人は大喜びで中に入りました。\nしかし、扉を開けるたびに不思議な注文が書かれていました。\n「鉄砲と弾丸をお置きください」「帽子と外套をお脱ぎください」「靴の泥をお落としください」。\n二人は「よほど格式の高い料理店なのだろう」と解釈して、言われる通りにしました。\n奥へ進むと、今度は「塩と酢をよく体に揉み込んでください」という注文が現れました。\nその時、二人はぞっとしました。\n料理を食べるのではなく、自分たちが「山猫の化け物に食べられる側」なのだと気づいたのです。\n二人は震え上がり、泣き出しました。\nその時、連れていた二匹の猟犬が扉を蹴破って飛び込んできました。\n激しい唸り声とともに館は煙のように消え失せ、二人は草むらに取り残されていました。\n命からがら逃げ帰った二人の紙くずのようになった顔の皺は、東京へ帰っても二度と治りませんでした。"
