    "summary": "Cụ ông hiền lành đánh rơi nắm cơm xuống hang chuột và được đàn chuột mở tiệc ca hát cảm ơn, đối lập với lòng tham của kẻ xấu tính.",
    "content": "むかしむかし、ある山里に、心優しい おじいさんが すんでいました。\nある日、おじいさんは 山へ 木を 切りに行きました。\n\nお昼になり、おじいさんは 切り株に 腰をかけて、おばあさんが 作ってくれた おむすびを 食べようと しました。\nところが、うっかり 手を 滑らせて、おむすびが 一つ、コロコロ、コロコロと 転がっていきました。\n「これこれ、待ちなさい。」\nおむすびは 坂道を 転がり落ちて、地面の 小さな 穴の中に すぽんと 落ちて しまいました。\n\nおじいさんが 穴を 覗き込むと、中から 楽しそうな 可愛い 歌声が 聞こえてきました。\n「おむすび ころりん すっとんとん。\nころころ ころりん すっとんとん。」\nおじいさんは とても 不思議に 思い、もう一つの おむすびも 穴に 転がして みました。\nすると、またまた 穴の 底から、\n「おむすび ころりん すっとんとん。\nころころ ころりん すっとんとん。」\nと、賑やかな 声が 聞こえます。\n\nおじいさんは 面白くなって、もっと よく 見ようと 穴を 覗き込みました。\nすると、足を 滑らせて、自分も 穴の中に ころりん、すっとんとんと 落ちて しまいました。\n\n穴の 底には、たくさんの ネズミたちが いました。\nネズミたちは おじいさんを 見て、大喜びで 迎えました。\n「おじいさん、美味しい おむすびを ありがとうございました。お礼に ご馳走を 差し上げます。」\nネズミたちは 歌ったり 踊ったり、美味しい お餅や 料理を たくさん 出してくれました。\n\n楽しい 時間が 過ぎ、おじいさんが 家に 帰る 時間に なりました。\nネズミの 親分は、大きな つづらと 小さな つづらを 持ってきました。\n「お礼の 宝物です。どちらでも 好きな方を お持ち帰りください。」\n欲のない おじいさんは、\n「わしは 年寄りだから、小さな つづらで 十分じゃよ。」\nと言って、小さな つづらを 背負って 帰りました。\n\n家に 帰って おばあさんと 一緒に つづらを 開けてみると、中から 金や 銀、色とりどりの 宝石が ザクザクと 出てきました。\n二人は 貧しい 村の人たちにも 分けてあげて、仲良く 幸せに 暮らしましたとさ。",
