    "content": "むかしむかし、海の近くの 小さな 村に、浦島太郎という 心優しい 漁師が いました。\n\nある日、太郎が 浜辺を 歩いていると、子どもたちが 大きな 亀を いじめていました。\n太郎は 子どもたちに お金を あげて、亀を 助けて 海へ 逃がして やりました。\n\n数日後、太郎が 海で 釣りを していると、あの 亀が 現れました。\n「太郎さん、先日は 助けていただき ありがとうございました。お礼に、海の底の 竜宮城へ ご案内します。」\n太郎が 亀の 背中に 乗ると、亀は 深い 海の中へ 潜っていきました。\n\n竜宮城は 夢のように 美しい お城でした。\n美しい 乙姫様が 太郎を 笑顔で 迎え、魚たちの 華やかな 踊りと ご馳走で もてなしました。\n太郎は 楽しくて、時間の 経つのも 忘れて 過ごしました。\n\nしかし、何日か 経つと、残してきた 年老いた 母のことが 心配になりました。\n「乙姫様、村へ 帰らなければ なりません。」\n乙姫様は 悲しそうに 言いました。\n「太郎さん、お別れに この 玉手箱を 差し上げます。困ったときに 開けてください。ただし、それまでは 決して 開けては なりませんよ。」\n\n浜辺に 戻った 太郎は 驚きました。村の 様子が すっかり 変わっていたのです。\n自分の 家も なく、知っている 人も 誰も いません。\n老人に 尋ねると、「浦島太郎？ その人なら 三百年も 昔に 海へ 出たきり 帰らなかった人ですよ」と 言われました。\n竜宮城の 数日は、地上の 三百年だったのです。\n\n悲しみに 暮れた 太郎は、約束を 忘れ、玉手箱を そっと 開けてしまいました。\n中から 白い 煙が もくもくと 立ち上り、それを 浴びた 太郎は 一瞬にして 白髪の おじいさんに なって しまいました。",
