    "content": "むかしむかし、ある山里に、貧しいけれど 心の 優しい おじいさんと おばあさんが すんでいました。\n\n大晦日の 日、お正月のお餅を買うお金がありませんでした。\nおじいさんは 作った 五つの 菅笠（すげがさ）を 売りに 町へ 行きましたが、雪が 激しく 降り、笠は 一つも 売れませんでした。\n\nとぼとぼと 帰る 道の 途中で、六体の お地蔵様が 雪を かぶって 寒そうに 並んで 立っていました。\n「ああ、お地蔵様、冷たい 雪を かぶって お気の毒に。」\nおじいさんは、売れ残った 五つの 笠を お地蔵様たちの 頭に かぶせました。\nしかし、笠が 一つ 足りません。おじいさんは 自分の 古い 笠を 脱いで、最後の お地蔵様に かぶせました。\n\n手ぬぐいを 頭に 巻いて 帰ってきた おじいさんの 話を 聞いて、おばあさんは にっこり 笑いました。\n「それは 良いことを なさいましたね。お餅は なくても、温かい お粥が あれば 幸せですよ。」\n\nその 夜更けのことでした。\n遠くから「よいしょ、よいしょ。笠売りの じいさんの 家は どこだ」と 不思議な 歌声が 聞こえてきました。\nドサリ！ と 重い 音が して 静かに なりました。\n戸を 開けてみると、そこには 米俵や お餅、野菜、そして 黄金の 財宝が 山のように 積まれていました。\n見ると、笠を かぶった 六人の お地蔵様が、静かに 雪道を 去っていく 後ろ姿が 見えました。",
