    "summary": "Chàng trai cứu hạc mắc bẫy tuyết. Một cô gái bí ẩn xuất hiện dệt nên tấm vải lụa thần kỳ bằng chính lông vũ của mình.",
    "content": "むかしむかし、雪深い 山里に、心の 優しい 貧しい 若者が すんでいました。\n\nある 冬の 寒い日、若者は 罠に かかって 苦しんでいる 一羽の 鶴を 見つけ、助けて やりました。\n鶴は 嬉しそうに 鳴き声を 上げ、空高く 飛んでいきました。\n\nその日の 夜、激しい 吹雪の 中、美しい 若い 娘が 一晩の 宿を 求めて やってきました。\n娘は 気立てが 良く、働き者で、やがて 二人は 夫婦に なりました。\n\nある日、妻は 奥の 部屋で 機（はた）を 織り始めました。\n「私が 織っている間は、決して 部屋を 覗かないで くださいね。」\n三日後、妻が 持ってきた 布は、光り輝く 息をのむほど 見事な 織物でした。\n布は 町で 大金で 売れ、家は 豊かに なりました。\n\nしかし、欲が出た 若者は、もう一度 織ってほしいと 頼みました。\n妻が 部屋に こもって 機を 織る 音を 聞いているうち、若者は 好奇心に 負け、約束を 破って 障子の 隙間から 部屋を 覗いて しまいました。\n\nそこに いたのは、人間ではなく、一羽の やせ細った 鶴でした。\n鶴は 自分の 羽根を 一本一本 嘴で 抜き、糸に 織り込んでいたのです。\n\n正体を 見られた 鶴は、涙を 流して 言いました。\n「あなた、私は あの時 助けていただいた 鶴です。ご恩を 返したくて 参りましたが、姿を 見られた以上、もう ここには いられません。」\n鶴は 大きく 羽を 広げ、名残惜しそうに 家の 上を 三度 回ると、遠い 山の 彼方へ 飛び去っていきました。",
