    "summary": "Kiệt tác văn học thiếu nhi Nhật Bản đầy xúc động về chú cáo Gon cô độc tìm cách chuộc lại lỗi lầm với anh thợ săn Biyou.",
    "content": "これは、わたしが 小さいときに、村の 茂平という おじいさんから 聞いた お話です。\n\nむかしは、わたしたちの 村の 近くの 中山という ところに、小さなお城があって、中山さまという お殿さまが おられたそうです。\nその 中山から、少し はなれた 山の中に、「ごんぎつね」という いたずら好きの 子ぎつねが いました。\nごんは、ひとりぼっちの 小ぎつねで、しだの いっぱい しげった 森の中に 穴を ほって すんでいました。\n\nある 秋の 雨上がりの 日、ごんは 村の 小川で、兵十（ひょうじゅう）という 若者が 網で 魚を とっているのを 見かけました。\n兵十が いなくなった すきに、ごんは いたずら心を 起こし、魚籠（びく）の中の うなぎを つかみ出して 逃げ出しました。\nその うなぎは、兵十の 病気の お母さんのために とったものだったのです。\n何日かして、兵十の 家の前を 通ると、お母さんの 葬式が 行われていました。\n「ああ、おれが いたずらをして うなぎを とったから、兵十の お母さんは うなぎを 食べられずに 死んでしまったんだ。」\nごんは 深く 後悔しました。\n\nそれからというもの、ごんは 兵十に つぐないを しようと、毎日 毎日、山で 拾った 栗や 松茸を、兵十の 家の 玄関に そっと 置いていくように なりました。\n「一体 誰が、毎日 栗や 松茸を 届けてくれるのだろう。きっと 神様が 恵んでくださるに 違いない。」\n兵十は 不思議に 思っていました。\n\nある 月の 綺麗な 夜、ごんが また 栗を 抱えて 兵十の 家に 入っていきました。\n兵十は、納屋から ふと 物音を 聞きつけました。\n「あいつは、いつかの いたずら狐だ！ また 何か 悪さを しに来たな。」\n兵十は 火縄銃を 手に取り、足音を 忍ばせて 近づくと、ズドン！ と 引き金を 引きました。\n\n倒れた ごんの そばに、こぼれ落ちた 栗が たくさん ありました。\n兵十は 驚いて 目を みはりました。\n「ごん、お前だったのか。いつも 栗を くれたのは……」\nごんは、ぐったりと 目を つぶったまま、うなずきました。\n兵十は 火縄銃を 取り落とし、青い 煙が まだ 筒口から 細く 出ていました。",
