    "content": "寒い 冬が 北から やってきて、森の 木々や 野原は 一面、真っ白な 雪に 覆われました。\n子ぎつねは 生まれて 初めて 見る 雪に 大喜びして、雪の上を 駆け回りました。\nしかし、しばらく 遊んでいるうちに、子ぎつねの お手々は 冷たさで 真っ赤に 凍えて しまいました。\n\n「お母ちゃん、手が 痛いよ。チクチクする。」\nお母さん狐は、可愛い わが子の 手を 息で 温めながら、町へ 行って 毛糸の 手袋を 買ってやろうと 決めました。\n\n夜になり、町へ 向かう 途中、お母さん狐は 子ぎつねの 片方の お手々を 握り、呪文を 唱えて、人間の 子どもの 手に 変えて やりました。\n「坊や、町へ 着いたら 帽子屋さんの 戸を トントンと 叩くのよ。\nそして、この 人間の 手の 方を 差し出して、『この 手に ちょうどいい 手袋を ください』と 言うのよ。決して、狐の 手を 出しては いけませんよ。」\nお母さん狐は、昔 人間に 追われた 怖い 記憶が あったので、町の 入口で 待つことに しました。\n\n子ぎつねは 町の 通りを トコトコ 歩き、帽子屋さんの 前に 着きました。\nガラス戸を トントンと 叩きます。\n中から「どなたですか」と 明かりが 差しました。\n子ぎつねは ドキドキして、慌てて まちがえて、本物の 狐の お手々を すき間から 出して しまいました。\n「この 手に ちょうどいい 手袋を ください。」\n\n帽子屋さんは びっくりしました。「おや、狐の 手だ。」\n木の手袋を 買いに来たなと 気づきましたが、白くて 小さな 可愛らしい 手を 見て、だます 気には なれませんでした。\n帽子屋さんは、一番 暖かそうな 毛糸の 手袋を 持ってきて、子ぎつねに 渡して やりました。\n\n子ぎつねは 大喜びで お母さんの もとへ 走って 帰りました。\n「お母ちゃん！ 人間って ちっとも 怖くないよ。狐の 手を 出したのに、優しい おじさんが 暖かな 手袋を くれたよ。」\nお母さん狐は びっくりして、目を 丸く しました。\nそして、夜の 森の 静けさの 中で、そっと つぶやきました。\n「本当に、人間は いいものかしら。本当に、人間は いいものかしらねえ……」",
