    "summary": "Hai thợ săn quý tộc kiêu ngạo đi lạc trong rừng sâu và bước vào một nhà hàng kỳ lạ mang tên Sơn Miêu Quán với những yêu cầu quái đản.",
    "content": "二人の 若い 紳士が、すっかり イギリスの 兵隊の かたちをして、ぴかぴかする 鉄砲を かついで、白熊のような 犬を 二匹 つれて、山奥を 歩いていました。\n\n山は 深く、風が どうどうと 吹き、木々は ざわざわと 鳴っていました。\n紳士たちは 獲物が 一匹も 捕れず、お腹が すいて 困り果てていました。\n「もう 帰ろう。腹が へって 死にそうだ。」\nそのとき、ふと うしろを 見ますと、立派な 西洋風の 一軒の 家が ありました。\n玄関には 瀬戸物の 青い 札が かかっていて、金色の 文字で こう 書かれていました。\n『西洋料理店　山猫軒（やまねこけん）』\n「これは ちょうどいい。ここで 食事を していこう。」\n\n二人が 扉を 開けて 入ると、ガラスの 戸が あり、裏側に こう 記されていました。\n『どなたも どうか お入りください。決して ご遠慮は ありません。』\n二人は 大喜びで 進みました。\n次の 扉には、\n『当軒は 注文の 多い 料理店ですから、どうか ご承知ください。』\nと あります。\n「注文が 多いというのは、人気があって 繁盛しているということだな。」二人は 得意になって うなずき合いました。\n\nしかし、奥へ 進むにつれて、扉に 書かれた 注文は だんだん 奇妙に なってきました。\n『鉄砲と 弾丸を ここに 置いてください。』\n『帽子と 外套、靴を お脱ぎください。』\n『ネクタイピンや カフスボタンなど、金物類を すべて お外しください。』\n二人は 言われるがままに 荷物を 外していきます。\n\nさらに 次の 扉には、壺が 置いてありました。\n『壺の 中の クリームを、顔や 手足に しっかり 塗り込んでください。』\n「外が 寒くて 肌が ひび割れないようにという、行き届いた 親切だな。」\n二人は 全身に クリームを ぬり合いました。\n\nそして、とうとう 最後の 扉に たどり着きました。\nそこには 大きな 青い 文字で、こう 書かれていたのです。\n『いろいろ ご注文が 多くて ご苦労さまでした。さあ、お皿の 上へ お乗りください。』\n二人は 顔を 見合わせました。\nガタガタと 震えが 止まりません。\n「ここは……西洋料理を 客に 食べさせる 店ではない！ 西洋料理として、客を 食べる 店だったんだ！」\n\n奥の 扉の 鍵穴から、ぎょろぎょろした 二つの 青い 目が、二人を じっと 覗き込んでいました。",
