    "content": "雨ニモマケズ\n風ニモマケズ\n雪ニモ夏ノ暑サニモマケヌ\n丈夫ナカラダヲモチ\n\n慾ハナク\n決シテ瞋ラズ\nイツモシヅカニワラッテヰル\n\n一日ニ玄米四合ト\n味噌ト少シノ野菜ヲタベ\n\nアラユルコトヲ\nジブンヲカンジョウニ入レズニ\nヨクミキキシワカリ\nソシテワスレズ\n\n野原ノ松ノ林ノ蔭ノ\n小サナ萱ブキノ小屋ニヰテ\n\n東ニ病気ノコドモアレバ\n行ッテ看病シテヤリ\n西ニツカレタ母アレバ\n行ッテソノ稲ノ束ヲ負ヒ\n南ニ死ニサウナ人アレバ\n行ッテコハガラナクテモイヽトイヒ\n北ニケンクヮヤソショウガアレバ\nツマラナイカラヤメロトイヒ\n\nヒデリノトキハナミダヲナガシ\nサムサノナツハオロオロアルキ\n\nミンナニデクノボートヨバレ\nホメラレモセズ\nクニモサレズ\n\nサウイフモノニ\nワタシハナリタイ",
