    "content": "件名：【有給休暇申請】業務引き継ぎおよび不在中の連絡先について（山田）\n\n営業部の皆様\nお疲れ様です。営業第2グループの山田です。\n\n私事で大変恐縮ですが、下記の日程にて有給休暇を取得させていただきたく存じます。\n\n■ 休暇取得日\n2026年10月15日（木）〜 2026年10月16日（金）（終日）\n※10月19日（月）より通常通り出社いたします。\n\n不在期間中の担当業務につきましては、以下の通り佐藤さんに引き継ぎをお願いしております。\n\n■ 業務引き継ぎ内容\n1. 株式会社ABC様：新規見積書のご提出\n　→ 見積書の作成は完了しており、佐藤さんより10月15日午前中にメール送付いただく予定です。\n2. XYZ商事様：納品スケジュールの進捗確認\n　→ 先方より進捗報告の連絡が入った場合、共有フォルダ「ABC案件」内の進行表へ反映をお願いしております。\n\n■ 不在中の緊急連絡先\n休暇期間中は基本的にメールの確認が困難となります。\n万が一、緊急を要する案件がございましたら、私の携帯電話（090-XXXX-XXXX）まで直接ご連絡いただけますと幸いです。\n\n皆様にはご迷惑とご不便をおかけいたしますが、何卒ご理解とご協力を賜りますようお願い申し上げます。\n\n--------------------------------------------------\n営業部 営業第2グループ\n山田 太郎 (Taro Yamada)\nTEL: 03-XXXX-XXXX / 内線: 1234\nE-mail: yamada@example.co.jp\n--------------------------------------------------"
